% Question 5
close all;
clc;

addpath('PhysioToolkitCardiacOutput_MatlabCode/2analyze');
addpath('PhysioToolkitCardiacOutput_MatlabCode/3estimate')

Fs = 125;

patients = {'s00020', 's00138', 's00214'};

for i = 1:length(patients) %[output:group:1517063e]
    % Get patient folder
    patientFolder = patients{i};

    abpFiles = dir(fullfile(patientFolder, '*_ABP.txt'));
    tcoFiles = dir(fullfile(patientFolder, '*n.txt'));

    % Load data
    ABP_timeseries = readmatrix(fullfile(patientFolder, abpFiles(1).name));
    TCO_data = readmatrix(fullfile(patientFolder, tcoFiles(1).name));

    % Print which patient it is
    fprintf('\nProcessing Patient %s\n', patients{i}); %[output:5de9dcd1] %[output:047eab88] %[output:846e9db8]

    % 1st 12 hours
    t_start_ABP = ABP_timeseries(1, 1);
    t_start_TCO = TCO_data(1, 1);

    ABP_window = ABP_timeseries(:, 1) < t_start_ABP + 12*60*60;
    TCO_window = TCO_data(:, 1) < t_start_TCO + 12*60*60;

    ABP_12h = ABP_timeseries(ABP_window, :);
    TCO_12h = TCO_data(TCO_window, :);

    ABP = ABP_12h(:, 2);

    % Extract ABP features
    onset = wabp(ABP);
    feat = abpfeature(ABP, onset);
    beatq = jSQI(feat, onset, ABP);

    % Parlikar estimation
    [X, t, tau] = parlikarCO(ABP, onset, feat, beatq, Fs, 9);
    %t = ABP_12h(1, 1)/60 + (onset(1:length(X)) - 1)/(Fs*60);

    % Thermodilution measurements
    TCO = TCO_12h(:, 16);
    validTCO = TCO > 0 & isfinite(TCO);

    TCO_valid = TCO(validTCO);
    time_TCO = TCO_12h(validTCO, 1)/60;

    % Calibrate using 1st valid TCO measurement
    validX = isfinite(t) & isfinite(X) & X > 0;
   
    t_valid = t(validX);
    X_valid = X(validX);

    [t_valid, uniqueIndex] = unique(t_valid);
    X_valid = X_valid(uniqueIndex);

    X_matched = interp1(t_valid, X_valid, time_TCO, 'nearest', NaN);

    % C2 Calibration
    %firstIndex = find(validTCO, 1, 'first');
    firstIndex = find(isfinite(TCO_valid), 1, 'first');

    referenceCO = TCO_valid(firstIndex);
    referenceTime = time_TCO(firstIndex);

    calWindow = t > referenceTime - 1 & t <= referenceTime & isfinite(X) & X > 0;
    calValue = median(X(calWindow), 'omitnan');

    if isempty(calValue) || ~isfinite(calValue) || calValue <= 0
        error('No valid estimate in calibration window!');
    end

    k_C2 = referenceCO / calValue;
    CO_C2 = k_C2 * X;
    CO_C2_matched = k_C2 * X_matched;

    % C1 Calibration: least squares scaling using paired measurments
    validPairs = isfinite(X_matched) & X_matched > 0 & isfinite(TCO_valid);
    k_C1 = sum(X_matched(validPairs).*TCO_valid(validPairs)) / sum(X_matched(validPairs).^2);

    CO_C1 = k_C1 * X;
    CO_C1_matched = k_C1 * X_matched;

    % Excluded calibration measurement from performance evaluation (C2)
    evaluation = validPairs;
    evaluation(firstIndex) = false;

    reference = TCO_valid(evaluation);
    estimate_C2 = CO_C2_matched(evaluation);
    estimate_C1 = CO_C1_matched(evaluation);

    % C2 performance
    errorValues_C2 = estimate_C2 - reference;
    bias_C2 = mean(errorValues_C2);
    RMSE_C2 = sqrt(mean(errorValues_C2.^2));
    MAE_C2 = mean(abs(errorValues_C2));
    percentageError_C2 = 100*std(errorValues_C2) / mean(reference);
    RMSNE_C2 = 100 * RMSE_C2 / mean(reference);

    % C1 performance
    errorValues_C1 = estimate_C1 - reference;
    bias_C1 = mean(errorValues_C1);
    RMSE_C1 = sqrt(mean(errorValues_C1.^2));
    MAE_C1 = mean(abs(errorValues_C1));
    percentageError_C1 = 100*std(errorValues_C1) / mean(reference);
    RMSNE_C1 = 100 * RMSE_C1 / mean(reference);

    fprintf('\nParlikar performance - %s\n', patients{i}); %[output:6f8e2325] %[output:48374ddd] %[output:1b26a97b]
    fprintf('Calibration  C2          C1\n'); %[output:8432500e] %[output:00354ec3] %[output:3d07a1e0]
    fprintf('Factor     %.4f        %4f\n', k_C2, k_C1); %[output:167900f0] %[output:358d421f] %[output:9aeba9f3]
    fprintf('Bias:      %.3f        %.3f\n', bias_C2, bias_C1); %[output:0f632edd] %[output:2a4da997] %[output:537ca6ec]
    fprintf('RMSE:      %.3f        %.3f\n', RMSE_C2, RMSE_C1); %[output:232eab24] %[output:1fd5e61d] %[output:0062ccdd]
    fprintf('MAE:       %.3f        %.3f\n', MAE_C2, MAE_C1); %[output:7db41309] %[output:54630ca7] %[output:02fa1f7f]
    fprintf('Percentage error: %2f%%      %2f%%\n', percentageError_C2, percentageError_C1); %[output:17c6b1fa] %[output:9fb063ce] %[output:6cc0bf22]
    fprintf('RMSNE:     %2f%%     %2f%%\n', RMSNE_C2, RMSNE_C1); %[output:6d606bb2] %[output:4f41bcc9] %[output:3f0491f8]

    % Plot Parlikar and thermodilution CO
    figure; %[output:24a4853d] %[output:90a9f478] %[output:9c54fde5]

    plot(t, CO_C2, 'LineWidth', 1.2); %[output:24a4853d] %[output:90a9f478] %[output:9c54fde5]
    hold on;

    stem(time_TCO, TCO_valid, 'r', 'LineWidth', 1.2, 'MarkerSize', 3)
    plot(time_TCO, TCO_valid, 'r:o', 'LineWidth', 1.2, 'MarkerSize', 3)
    xlabel('Time (minutes)');
    ylabel('Cardiac Output (L/min)');
    title('Parlikar CO Estimate - ', patients{i});
    legend('ECO', 'TCO');
    xlim([0 720]);
    grid on;

    saveas(gcf, sprintf('Q5_Parlikar_CO_Estimate_%s.png', patients{i}));

    % Plot estimated tau
    figure; %[output:20acbb48] %[output:3b81e183] %[output:771af759]

    plot(t, tau, 'LineWidth', 1.2); %[output:20acbb48] %[output:3b81e183] %[output:771af759]
    xlabel('Time (minutes)');
    ylabel('Tau (seconds)');
    title('Parlikar Time Constant (Tau) Estimate', patients{i});
    xlim([0 720])
    grid on;

    saveas(gcf, sprintf('Q5_Parlikar_Tau_Estimate_%s.png', patients{i}));

    % Plot C1 and C2 together
    figure; %[output:8cf67c28] %[output:89c07ee6] %[output:9d92f436]

    plot(t, CO_C2, 'LineWidth', 1.2); %[output:8cf67c28] %[output:89c07ee6] %[output:9d92f436]
    hold on;

    plot(t, CO_C1, 'LineWidth', 1.2);
    stem(time_TCO, TCO_valid, 'LineWidth', 1.2);

    xlabel('Time (minutes)');
    ylabel('Cardiac Output (L/min)');
    title(sprintf('Parlikar CO Calibration Comparison - %s', patients{i}));
    legend('C2', 'C1', 'Thermodilution', 'Location', 'best');
    xlim([0 720])
    grid on;

    saveas(gcf, sprintf('Q5_Parlikar_CO_C1_C2_%s.png', patients{i}));

end %[output:group:1517063e]

